  const unit=loaded.byId.get(id);assert.deepEqual(unit,g.root_record);assert.equal(rootDigest(unit,loaded.canon.books[unit.book]),g.root_sha256);assert.equal(validateLink(declared.links[id],id,unit,loaded.canon.books[unit.book]),p);
